mapper.select:
SELECT r.id, r.article_id, r.reviewer_id, u.display_name AS reviewer_name, r.decision, r.comment, r.article_version, r.created_at FROM cms_review_record r JOIN sys_user u ON u.id = r.reviewer_id
AND r.article_id = #{q.articleId} AND r.decision = #{q.decision}
ORDER BY r.created_at DESC, r.id DESC
